from itertools import combinations, product
from collections import Counter


def _temporal(data, exact, minimum):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    coupons = data["coupons"]
    initial_mask = bits.get(source, 0)
    initial = (source, initial_mask, 0)
    distance = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, spent = heapq.heappop(queue)
        state = (node, mask, spent)
        if distance.get(state) != time:
            continue
        if (node == data["target"] and mask == full
                and (not exact or spent == coupons)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for use in (0, 1):
                if use and spent == coupons:
                    continue
                duration = edge["duration"]
                if use:
                    duration = max(minimum, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], mask | bits.get(edge["v"], 0), spent + use)
                if arrival < distance.get(next_state, float("inf")):
                    distance[next_state] = arrival
                    heapq.heappush(queue, (arrival, *next_state))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    choices = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + sorted(versions))

    best_vector = None
    best_installation = None
    for assignment in product(*choices):
        installed = {name: version for name, version in zip(names, assignment)
                     if version is not None}
        if any(name not in installed or not low <= installed[name] <= high
               for name, (low, high) in roots.items()):
            continue

        edges = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in installed
                        or not dep["min"] <= installed[target] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be precisely the closure reachable from roots.
        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if name not in edges:
                continue
            pending.extend(edges[name])
        if reachable != set(installed):
            continue

        active, finished = set(), set()

        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in edges):
            continue

        vector = tuple(installed.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_installation = installed

    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def _quota_intervals(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in set(data.get("blocked", []))]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        valid = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in subset)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids > best_ids)):
            best_value = value
            best_ids = sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


